  await page.getByRole('link',{name:'工作区设置'}).click();await expect(page.getByRole('button',{name:'成员',exact:true})).toHaveCount(0);
  await page.getByRole('button',{name:'运营账号',exact:true}).click();await page.getByRole('button',{name:'添加账号',exact:true}).click();await page.getByLabel('小红书主页链接或内部账号 ID').fill('abcdefabcdefabcdefabcd01');await page.getByLabel('名称',{exact:false}).fill('真实标识测试账号');await page.getByRole('button',{name:'保存账号',exact:true}).click();await expect(page.getByRole('dialog')).toContainText('账号已保存');await page.getByRole('button',{name:'关闭详情'}).click();await expect(page.getByRole('cell',{name:'真实标识测试账号'})).toBeVisible();
