  await page.getByRole('button',{name:'运营账号',exact:true}).click();await page.context().clearCookies();await page.reload();await page.getByRole('button',{name:'运营账号',exact:true}).click();await expect(page.getByRole('cell',{name:'真实标识测试账号'})).toBeVisible();
