test('服务错误可重试，请求凭据失效不返回登录页面',async({page})=>{
 await page.goto('/');await expect(page.getByRole('heading',{name:'欢迎使用YOYO'})).toBeVisible();
 await page.route('**/api/v1/settings',async route=>{await new Promise(r=>setTimeout(r,300));await route.fulfill({status:503,contentType:'application/json',body:JSON.stringify({error:{code:'SERVICE_UNAVAILABLE',message:'测试服务不可用'}})});});
 await page.getByRole('link',{name:'工作区设置'}).click();await expect(page.getByRole('status')).toContainText('正在加载');await expect(page.getByRole('alert')).toContainText('测试服务不可用');await page.unroute('**/api/v1/settings');await page.getByRole('button',{name:'重试'}).click();
 let fail=true;await page.route('**/api/v1/settings',route=>{if(route.request().method()==='PATCH'&&fail){fail=false;return route.fulfill({status:403,contentType:'application/json',body:JSON.stringify({error:{code:'CSRF_INVALID',message:'请求凭据已失效，请重试'}})});}return route.continue();});
 await page.getByRole('button',{name:'保存设置'}).click();await expect(page.getByRole('alert')).toContainText('请求凭据已失效');await expect(page.getByLabel('邮箱')).toHaveCount(0);await page.getByRole('button',{name:'保存设置'}).click();await expect(page.getByRole('status')).toContainText('已保存');
});

